/*
===============================================================================
 SMASH-VN: TẠO MỚI VÀ RESET TOÀN BỘ DỮ LIỆU SẢN PHẨM (ID ĐẸP TỪ 1, VỢT 3 THUỘC TÍNH)
 Mô tả:
   1. Xóa sạch dữ liệu sản phẩm cũ, reset identity về 0.
   2. Cấu hình DanhMucThuocTinh: Vợt cầu lông CHỈ CÓ 3 THUỘC TÍNH: Màu sắc, Sức căng, Độ cứng.
   3. Nạp 57 sản phẩm chính hãng với ID từ 1 đến 57, mã SP000001 -> SP000057.
   4. Nạp các biến thể với SKU đẹp, tồn kho, giá bán và liên kết đúng ảnh có sẵn trên đĩa.
   5. Nạp phiếu nhập kho khởi tạo PN000001 để đồng bộ số lượng tồn kho.
===============================================================================
*/
USE [BadmintonShopDB1];
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET NOCOUNT ON;
BEGIN TRANSACTION;
BEGIN TRY
    PRINT N'1. Đang dọn dẹp dữ liệu sản phẩm cũ...';
    DELETE FROM [dbo].[CommentViolationLog];
    DELETE FROM [dbo].[HinhAnhDanhGia];
    DELETE FROM [dbo].[DanhGia];
    DELETE FROM [dbo].[GioHangChiTiet];
    DELETE FROM [dbo].[HoaDonChiTiet];
    DELETE FROM [dbo].[PhieuNhapChiTiet];
    DELETE FROM [dbo].[PhieuNhap];
    DELETE FROM [dbo].[SanPhamYeuThich];
    DELETE FROM [dbo].[SanPham_DotGiamGia];
    DELETE FROM [dbo].[HinhAnhSanPham];
    DELETE FROM [dbo].[SanPhamChiTietThuocTinh];
    DELETE FROM [dbo].[SanPhamChiTiet];
    DELETE FROM [dbo].[SanPham];

    PRINT N'2. Đang reset bộ đếm IDENTITY về 0...';
    DBCC CHECKIDENT ('[dbo].[SanPham]', RESEED, 0);
    DBCC CHECKIDENT ('[dbo].[SanPhamChiTiet]', RESEED, 0);
    DBCC CHECKIDENT ('[dbo].[HinhAnhSanPham]', RESEED, 0);
    DBCC CHECKIDENT ('[dbo].[SanPhamChiTietThuocTinh]', RESEED, 0);
    DBCC CHECKIDENT ('[dbo].[PhieuNhap]', RESEED, 0);
    DBCC CHECKIDENT ('[dbo].[PhieuNhapChiTiet]', RESEED, 0);
    DBCC CHECKIDENT ('[dbo].[HoaDonChiTiet]', RESEED, 0);
    DBCC CHECKIDENT ('[dbo].[GioHangChiTiet]', RESEED, 0);
    DBCC CHECKIDENT ('[dbo].[DanhGia]', RESEED, 0);
    DBCC CHECKIDENT ('[dbo].[HinhAnhDanhGia]', RESEED, 0);
    DBCC CHECKIDENT ('[dbo].[CommentViolationLog]', RESEED, 0);

    PRINT N'3. Cấu hình thuộc tính danh mục: Vợt cầu lông CHỈ CÓ 3 THUỘC TÍNH (Màu sắc, Sức căng, Độ cứng)...';
    DELETE FROM [dbo].[DanhMucThuocTinh] WHERE [id_danh_muc] = 1;
    -- Dọn dẹp các danh mục/thương hiệu rác nếu có
    DELETE FROM [dbo].[DanhMucThuocTinh] WHERE [id_danh_muc] NOT IN (1, 2, 3, 4, 5, 6, 7, 8);
    DELETE FROM [dbo].[DanhMuc] WHERE [id] NOT IN (1, 2, 3, 4, 5, 6, 7, 8);
    DELETE FROM [dbo].[ThuongHieu] WHERE [id] NOT IN (1, 2, 3, 4, 5, 6);
    DELETE FROM [dbo].[ThuocTinh] WHERE [id] NOT IN (1, 2, 3, 4, 5, 6, 7);

    PRINT N'4. Đang nạp 57 SanPham (ID 1 -> 57)...';
    SET IDENTITY_INSERT [dbo].[SanPham] ON;
    SET IDENTITY_INSERT [dbo].[SanPham] OFF;
    DBCC CHECKIDENT ('[dbo].[SanPham]', RESEED, 57);

    PRINT N'5. Đang nạp 136 SanPhamChiTiet (ID 1 -> 136)...';
    SET IDENTITY_INSERT [dbo].[SanPhamChiTiet] ON;
    SET IDENTITY_INSERT [dbo].[SanPhamChiTiet] OFF;
    DBCC CHECKIDENT ('[dbo].[SanPhamChiTiet]', RESEED, 136);

    PRINT N'6. Đang nạp 299 thuộc tính biến thể (SanPhamChiTietThuocTinh)...';
    SET IDENTITY_INSERT [dbo].[SanPhamChiTietThuocTinh] ON;
    SET IDENTITY_INSERT [dbo].[SanPhamChiTietThuocTinh] OFF;
    DBCC CHECKIDENT ('[dbo].[SanPhamChiTietThuocTinh]', RESEED, 299);

    PRINT N'7. Đang nạp 446 HinhAnhSanPham...';
    SET IDENTITY_INSERT [dbo].[HinhAnhSanPham] ON;
    SET IDENTITY_INSERT [dbo].[HinhAnhSanPham] OFF;
    DBCC CHECKIDENT ('[dbo].[HinhAnhSanPham]', RESEED, 446);

    PRINT N'8. Đang nạp Phiếu nhập khởi tạo ban đầu (PN000001)...';
    SET IDENTITY_INSERT [dbo].[PhieuNhap] ON;
    SET IDENTITY_INSERT [dbo].[PhieuNhap] OFF;
    DBCC CHECKIDENT ('[dbo].[PhieuNhap]', RESEED, 1);

    PRINT N'9. Đang nạp 136 chi tiết phiếu nhập (PhieuNhapChiTiet)...';
    SET IDENTITY_INSERT [dbo].[PhieuNhapChiTiet] ON;
    SET IDENTITY_INSERT [dbo].[PhieuNhapChiTiet] OFF;
    DBCC CHECKIDENT ('[dbo].[PhieuNhapChiTiet]', RESEED, 136);

    COMMIT TRANSACTION;
    PRINT N'===========================================================';
    PRINT N'===> ĐÃ RESET VÀ TẠO MỚI THÀNH CÔNG DỮ LIỆU CHUẨN ĐẸP!';
    PRINT N'===> Tổng sản phẩm: 57 (ID 1 -> 57)';
    PRINT N'===> Tổng biến thể: 136 (ID 1 -> 136)';
    PRINT N'===> Toàn bộ vợt cầu lông đã được chuẩn hóa ĐÚNG 3 THUỘC TÍNH: Màu sắc, Sức căng, Độ cứng!';
    PRINT N'===========================================================';
END TRY
BEGIN CATCH
    ROLLBACK TRANSACTION;
    PRINT N'LỖI KHI TẠO DỮ LIỆU: ' + ERROR_MESSAGE();
    THROW;
END CATCH;
GO
